ALTER TABLE public.salons ALTER COLUMN name SET DEFAULT '';
ALTER TABLE public.salons ADD COLUMN logo_url text NOT NULL DEFAULT '', ADD COLUMN name_article text NOT NULL DEFAULT 'da', ADD COLUMN timezone text NOT NULL DEFAULT 'America/Sao_Paulo';
CREATE TABLE public.salon_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), user_id uuid NOT NULL, professional_id uuid REFERENCES public.professionals(id), access text NOT NULL DEFAULT 'PROFISSIONAL', email text NOT NULL DEFAULT '', UNIQUE(salon_id,user_id), CHECK(access IN ('ADMIN','PROFISSIONAL')));
GRANT SELECT ON public.salon_members TO authenticated; GRANT ALL ON public.salon_members TO service_role;
ALTER TABLE public.salon_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.manages_salon(_salon uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.owns_salon(_salon) OR public.has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM public.salon_members WHERE salon_id=_salon AND user_id=auth.uid() AND access='ADMIN') $$;
CREATE FUNCTION public.belongs_salon(_salon uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.manages_salon(_salon) OR EXISTS(SELECT 1 FROM public.salon_members WHERE salon_id=_salon AND user_id=auth.uid()) $$;
CREATE POLICY members_read ON public.salon_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.manages_salon(salon_id));
CREATE POLICY salons_member_read ON public.salons FOR SELECT TO authenticated USING(public.belongs_salon(id));
CREATE TABLE public.professions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), name text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.professions TO authenticated; GRANT ALL ON public.professions TO service_role;
ALTER TABLE public.professions ENABLE ROW LEVEL SECURITY;
CREATE POLICY professions_read ON public.professions FOR SELECT TO authenticated USING(public.belongs_salon(salon_id));
CREATE POLICY professions_manage ON public.professions FOR ALL TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
ALTER TABLE public.professionals ADD COLUMN profession_id uuid REFERENCES public.professions(id), ADD COLUMN photo_url text NOT NULL DEFAULT '';
ALTER TABLE public.professionals ALTER COLUMN commission_pct SET DEFAULT 0;
CREATE POLICY professionals_manage ON public.professionals FOR ALL TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
CREATE POLICY services_manage ON public.services FOR ALL TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
CREATE TABLE public.config_agente_secretario (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL UNIQUE REFERENCES public.salons(id), nome_agente text NOT NULL DEFAULT '', genero text NOT NULL DEFAULT 'neutro', pronomes text NOT NULL DEFAULT 'elu/delu', CHECK(genero IN ('masculino','feminino','neutro')));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.config_agente_secretario TO authenticated; GRANT ALL ON public.config_agente_secretario TO service_role;
ALTER TABLE public.config_agente_secretario ENABLE ROW LEVEL SECURITY;
CREATE POLICY secretary_manage ON public.config_agente_secretario FOR ALL TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
CREATE TABLE public.salon_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL UNIQUE REFERENCES public.salons(id), evolution_url text NOT NULL DEFAULT '', evolution_instance text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.salon_connections TO authenticated; GRANT ALL ON public.salon_connections TO service_role;
ALTER TABLE public.salon_connections ENABLE ROW LEVEL SECURITY;
CREATE POLICY connections_manage ON public.salon_connections FOR ALL TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
CREATE TABLE public.salon_clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), name text NOT NULL DEFAULT '', whatsapp text NOT NULL DEFAULT '', birthday date, last_visit timestamptz, total_visits integer NOT NULL DEFAULT 0, consent boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.salon_clients TO authenticated; GRANT ALL ON public.salon_clients TO service_role;
ALTER TABLE public.salon_clients ENABLE ROW LEVEL SECURITY;
CREATE POLICY clients_manage ON public.salon_clients FOR ALL TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
CREATE TABLE public.team_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), sender_id uuid NOT NULL DEFAULT auth.uid(), recipient_id uuid, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.team_messages TO authenticated; GRANT ALL ON public.team_messages TO service_role;
ALTER TABLE public.team_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY team_read ON public.team_messages FOR SELECT TO authenticated USING(public.belongs_salon(salon_id) AND (recipient_id IS NULL OR recipient_id=auth.uid() OR sender_id=auth.uid() OR public.manages_salon(salon_id)));
CREATE POLICY team_send ON public.team_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.belongs_salon(salon_id) AND (recipient_id IS NULL OR EXISTS(SELECT 1 FROM public.salon_members m WHERE m.user_id=recipient_id AND m.salon_id=team_messages.salon_id)));
ALTER PUBLICATION supabase_realtime ADD TABLE public.team_messages;
CREATE TABLE public.supplier_brands (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), name text NOT NULL DEFAULT '', whatsapp text NOT NULL DEFAULT '', contact_name text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.supplier_brands TO authenticated; GRANT ALL ON public.supplier_brands TO service_role;
ALTER TABLE public.supplier_brands ENABLE ROW LEVEL SECURITY;
CREATE POLICY brands_manage ON public.supplier_brands FOR ALL TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
CREATE TABLE public.supplier_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), brand_id uuid NOT NULL REFERENCES public.supplier_brands(id), name text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.supplier_products TO authenticated; GRANT ALL ON public.supplier_products TO service_role;
ALTER TABLE public.supplier_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_manage ON public.supplier_products FOR ALL TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
CREATE TABLE public.supplier_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), brand_id uuid NOT NULL REFERENCES public.supplier_brands(id), items jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'pendente', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.supplier_orders TO authenticated; GRANT ALL ON public.supplier_orders TO service_role;
ALTER TABLE public.supplier_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY orders_manage ON public.supplier_orders FOR ALL TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
CREATE TABLE public.month_closings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), month text NOT NULL, revenue numeric NOT NULL DEFAULT 0, commissions numeric NOT NULL DEFAULT 0, closed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(salon_id,month));
GRANT SELECT,INSERT ON public.month_closings TO authenticated; GRANT ALL ON public.month_closings TO service_role;
ALTER TABLE public.month_closings ENABLE ROW LEVEL SECURITY;
CREATE POLICY closing_read ON public.month_closings FOR SELECT TO authenticated USING(public.manages_salon(salon_id));
CREATE POLICY closing_insert ON public.month_closings FOR INSERT TO authenticated WITH CHECK(public.manages_salon(salon_id));
ALTER TABLE public.appointments ADD COLUMN salon_client_id uuid REFERENCES public.salon_clients(id), ADD COLUMN applied_commission_pct numeric, ADD COLUMN commission_amount numeric, ADD COLUMN salon_amount numeric, ADD COLUMN payment_status text NOT NULL DEFAULT 'pendente', ADD COLUMN duration_min integer NOT NULL DEFAULT 60;
CREATE POLICY appointments_manager ON public.appointments FOR ALL TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
CREATE POLICY appointments_staff_read ON public.appointments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.salon_members m WHERE m.user_id=auth.uid() AND m.salon_id=appointments.salon_id AND m.professional_id=appointments.professional_id));
CREATE POLICY appointments_staff_update ON public.appointments FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.salon_members m WHERE m.user_id=auth.uid() AND m.salon_id=appointments.salon_id AND m.professional_id=appointments.professional_id)) WITH CHECK(EXISTS(SELECT 1 FROM public.salon_members m WHERE m.user_id=auth.uid() AND m.salon_id=appointments.salon_id AND m.professional_id=appointments.professional_id));
CREATE FUNCTION public.validate_salon_appointment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE _pct numeric; _service public.services; _recipient uuid;
BEGIN
IF NOT EXISTS(SELECT 1 FROM public.professionals WHERE id=new.professional_id AND salon_id=new.salon_id) THEN RAISE EXCEPTION 'Profissional não pertence ao salão'; END IF;
IF new.service_id IS NOT NULL THEN SELECT * INTO _service FROM public.services WHERE id=new.service_id AND salon_id=new.salon_id; IF NOT FOUND THEN RAISE EXCEPTION 'Serviço não pertence ao salão'; END IF; END IF;
IF new.salon_client_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.salon_clients WHERE id=new.salon_client_id AND salon_id=new.salon_id) THEN RAISE EXCEPTION 'Cliente não pertence ao salão'; END IF;
IF TG_OP='UPDATE' AND auth.uid() IS NOT NULL AND NOT public.manages_salon(old.salon_id) THEN
 IF (to_jsonb(new)-ARRAY['status','starts_at']) IS DISTINCT FROM (to_jsonb(old)-ARRAY['status','starts_at']) THEN RAISE EXCEPTION 'Você só pode remarcar ou alterar o status'; END IF;
END IF;
IF TG_OP='INSERT' OR new.service_id IS DISTINCT FROM old.service_id THEN
 IF new.service_id IS NOT NULL THEN new.price:=_service.price; new.duration_min:=_service.duration_min; END IF;
 new.applied_commission_pct:=NULL; new.commission_amount:=NULL; new.salon_amount:=NULL;
END IF;
IF new.price<0 OR new.duration_min<=0 THEN RAISE EXCEPTION 'Valor ou duração inválida'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(new.professional_id::text,0));
IF new.status<>'cancelado' AND EXISTS(SELECT 1 FROM public.appointments a WHERE a.professional_id=new.professional_id AND a.id<>new.id AND a.status<>'cancelado' AND a.starts_at < new.starts_at + make_interval(mins=>new.duration_min) AND a.starts_at+make_interval(mins=>a.duration_min)>new.starts_at) THEN RAISE EXCEPTION 'Horário ocupado'; END IF;
IF TG_OP='UPDATE' AND old.status='finalizado' AND (new.status<>old.status OR new.price<>old.price OR new.service_id IS DISTINCT FROM old.service_id OR new.professional_id<>old.professional_id) THEN RAISE EXCEPTION 'Atendimento concluído não pode ser reaberto'; END IF;
IF new.status='finalizado' AND (TG_OP='INSERT' OR old.status<>'finalizado') THEN
 SELECT commission_pct INTO _pct FROM public.professionals WHERE id=new.professional_id;
 IF _pct<0 OR _pct>100 THEN RAISE EXCEPTION 'Comissão precisa ser entre 0 e 100'; END IF;
 new.applied_commission_pct:=_pct; new.commission_amount:=round(new.price*_pct/100,2); new.salon_amount:=new.price-new.commission_amount;
 IF new.salon_client_id IS NOT NULL THEN UPDATE public.salon_clients SET last_visit=new.starts_at,total_visits=total_visits+1 WHERE id=new.salon_client_id; END IF;
ELSIF TG_OP='UPDATE' THEN new.applied_commission_pct:=old.applied_commission_pct; new.commission_amount:=old.commission_amount; new.salon_amount:=old.salon_amount;
END IF;
IF new.status='chegou' AND (TG_OP='INSERT' OR old.status<>'chegou') THEN
 SELECT user_id INTO _recipient FROM public.salon_members WHERE professional_id=new.professional_id LIMIT 1;
 INSERT INTO public.team_messages(salon_id,sender_id,recipient_id,message) VALUES(new.salon_id,coalesce(auth.uid(),(SELECT owner_id FROM public.salons WHERE id=new.salon_id)),_recipient,'🔔 A cliente '||new.client_name||' chegou para seu atendimento.');
END IF;
RETURN new; END $$;
CREATE TRIGGER appointment_rules BEFORE INSERT OR UPDATE ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.validate_salon_appointment();
CREATE FUNCTION public.save_salon_identity(_salon uuid,_name text,_logo text,_color text,_article text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.manages_salon(_salon) THEN RAISE EXCEPTION 'Acesso restrito'; END IF; IF _article NOT IN ('da','do','de') OR _color !~ '^#[0-9A-Fa-f]{6}$' THEN RAISE EXCEPTION 'Configuração inválida'; END IF; UPDATE public.salons SET name=trim(_name),logo_url=_logo,brand_color=_color,name_article=_article WHERE id=_salon; END $$;
REVOKE ALL ON FUNCTION public.save_salon_identity(uuid,text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_salon_identity(uuid,text,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _role text:=coalesce(new.raw_user_meta_data->>'role','cliente'); _name text:=coalesce(new.raw_user_meta_data->>'full_name',''); _ref text:=new.raw_user_meta_data->>'ref'; _reseller uuid; BEGIN
INSERT INTO public.profiles(id,full_name,email) VALUES(new.id,_name,new.email);
IF _role NOT IN ('revendedor','dono_salao','cliente') THEN _role:='cliente'; END IF;
INSERT INTO public.user_roles(user_id,role) VALUES(new.id,_role::public.app_role) ON CONFLICT DO NOTHING;
IF _role='revendedor' THEN INSERT INTO public.resellers(user_id,code) VALUES(new.id,upper(substr(replace(new.id::text,'-',''),1,8)));
ELSIF _role='dono_salao' THEN SELECT user_id INTO _reseller FROM public.resellers WHERE lower(code)=lower(_ref) AND user_id<>new.id;
INSERT INTO public.salons(owner_id,name,slug,city,plan_id,reseller_id) VALUES(new.id,coalesce(new.raw_user_meta_data->>'salon_name',''),'salao-'||replace(new.id::text,'-',''),new.raw_user_meta_data->>'city',(SELECT id FROM public.plans WHERE name='Pro'),_reseller);
END IF; RETURN new; END $$;